<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config.php';require_once dirname(__DIR__).'/lib/common.php';require_once dirname(__DIR__).'/lib/provider.php';tp_admin_required();
[$df,$dt]=tp_window();$from=$_GET['from']??$df;$to=$_GET['to']??$dt;$port=trim((string)($_GET['port']??tp_port_code()));$rows=[];$err='';$total=0;$carriers=0;$shanghai=0;
if(isset($_GET['run'])){try{$rows=tp_fetch_vessels($from,$to,$port);$total=count($rows);foreach($rows as $r){if(tp_is_vehicle_carrier($r)){$carriers++;if(tp_is_shanghai_origin($r))$shanghai++;}}}catch(Throwable $e){$err=$e->getMessage();}}
?><!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>해수부 API 테스트</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f5f6f8}.table{font-size:.86rem}.wrap{max-width:1600px}.carrier td{background:#fff8dc!important}</style></head><body><div class="container-fluid wrap py-4"><h2>해수부 선박운항정보 API 테스트</h2><p class="text-secondary">v1.3 · Info5 · 전체 페이지 자동조회 · 자동차운반선 자동분류</p><form class="row g-2 mb-3"><input type="hidden" name="run" value="1"><div class="col-md-3"><label class="form-label">시작일</label><input type="date" class="form-control" name="from" value="<?=h($from)?>"></div><div class="col-md-3"><label class="form-label">종료일</label><input type="date" class="form-control" name="to" value="<?=h($to)?>"></div><div class="col-md-2"><label class="form-label">항만청코드</label><input class="form-control" name="port" value="<?=h($port)?>" maxlength="3"></div><div class="col-md-4 d-flex align-items-end"><button class="btn btn-dark w-100">전체 조회</button></div></form>
<?php if($err):?><div class="alert alert-danger"><b>API 호출 오류</b><pre class="mb-0 mt-2" style="white-space:pre-wrap"><?=h($err)?></pre></div><?php endif?>
<?php if(isset($_GET['run'])&&!$err):?><div class="alert alert-success">정상 응답 · 전체 페이지 합계 <b><?=number_format($total)?>건</b> · 자동차운반선 <b><?=number_format($carriers)?>건</b> · 중국발 우선후보 <b><?=number_format($shanghai)?>건</b><?php if($rows):?> · 항구청명 <b><?=h($rows[0]['port_name'])?></b><?php endif?></div><div class="table-responsive"><table class="table table-sm table-striped align-middle"><thead><tr><th>후보</th><th>입항일시</th><th>선박명</th><th>호출부호</th><th>종류</th><th>전출항지</th><th>항구</th><th>선석</th><th>양하톤</th><th>적하목록관리번호</th><th>신고업체</th></tr></thead><tbody><?php foreach($rows as $r):$vc=tp_is_vehicle_carrier($r);$cn=$vc&&tp_is_china_origin($r);?><tr class="<?=$vc?'carrier':''?>"><td><?php if($cn):?><span class="badge text-bg-danger">중국발 차량선</span><?php elseif($vc):?><span class="badge text-bg-warning">차량선</span><?php endif?></td><td><?=h($r['eta'])?></td><td><b><?=h($r['vessel_name'])?></b></td><td><?=h($r['call_sign'])?></td><td><?=h($r['vessel_kind'])?></td><td><?=h($r['origin_port'])?></td><td><?=h($r['port_name'])?></td><td><?=h($r['berth_name'])?></td><td><?=h($r['landing_ton'])?></td><td><?=h($r['manifest_no'])?></td><td><?=h($r['report_company'])?></td></tr><?php endforeach?></tbody></table></div><?php endif?><a class="btn btn-outline-secondary" href="index.php">관리자로</a> <a class="btn btn-outline-dark" href="carriers.php">자동차운반선 후보</a></div></body></html>
